"""Actualisation du choix de socle et des besoins de réception/déploiement."""
from pathlib import Path
import shutil


def appliquer(ctx):
    root=ctx['ROOT']; write=ctx['write_doc']; load=ctx['load_sections']; put=ctx['put']; table=ctx['table']; glossary=ctx['GLOSSARY']
    backup=root/'05-archives/versions/2026-10-16-reference-avant-matrix'
    snapshot_sources=[p for p in root.rglob('*.html') if 'versions' not in p.relative_to(root).parts]
    for source in snapshot_sources:
        rel=source.relative_to(root)
        dest=backup/rel
        if not dest.exists():
            dest.parent.mkdir(parents=True,exist_ok=True)
            shutil.copy2(root/rel,dest)
    # Le générateur principal conserve déjà la version précédant cette étude.
    # Les archives datées sont conservées telles quelles ; les notices précisent l'évolution.
    terms='<dl><dt>Matrix</dt><dd>Protocole de messagerie et synchronisation fédérée.</dd><dt>Element</dt><dd>Clients et solutions autour de Matrix ; ni le protocole ni le moteur d’un agent.</dd><dt>Synapse</dt><dd>Implémentation de serveur Matrix auto-hébergeable.</dd><dt>XMTP</dt><dd>Infrastructure de messagerie avec identités cryptographiques et chiffrement MLS.</dd><dt>Daemon local</dt><dd>Processus persistant autorisé, près de l’agent, qui synchronise et signale les messages.</dd><dt>Hors ligne intranet</dt><dd>Serveur et clients connectés au réseau local, sans dépendance à Internet ; distinct d’un ordinateur sans aucune connexion réseau.</dd><dt>Curseur</dt><dd>Repère de synchronisation persisté pour reprendre la lecture des événements.</dd><dt>Idempotence</dt><dd>Gestion permettant de recevoir plusieurs fois un événement sans répéter son effet applicatif.</dd></dl>'
    glossary+=terms
    refs=[
      ('Matrix — API clients, synchronisation, événements et E2EE','https://spec.matrix.org/latest/client-server-api/'),
      ('Matrix — Olm et Megolm','https://spec.matrix.org/v1.18/olm-megolm/'),
      ('Matrix Rust SDK — bibliothèque clients et bots','https://github.com/matrix-org/matrix-rust-sdk'),
      ('Synapse — dépôt maintenu et licence','https://github.com/element-hq/synapse'),
      ('Element — clients','https://element.io/app'),
      ('Element Server Suite Community — périmètre annoncé','https://element.io/server-suite/community'),
      ('XMTP — présentation et garanties annoncées','https://xmtp.org/'),
      ('XMTP — modèle d’identité','https://xmtp.org/protocol/identity/'),
      ('XMTP — migration, réseaux auto-hébergés et rattrapage','https://xmtp.org/get-started/migrate-to-self-hosted/'),
      ('XMTP — quickstart et versions recommandées','https://xmtp.org/get-started/quickstart/'),
      ('Claude Code — channels en research preview','https://code.claude.com/docs/en/channels'),
      ('Claude Code — contrat des channels','https://code.claude.com/docs/en/channels-reference'),
      ('OpenAI — protocole Codex App Server','https://developers.openai.com/codex/app-server/'),
      ('Gemini CLI — mode headless','https://geminicli.com/docs/cli/tutorials/automation/'),
      ('Gemini CLI — hooks','https://geminicli.com/docs/hooks/reference/'),
      ('MCP — évolution des abonnements','https://ts.sdk.modelcontextprotocol.io/v2/migration/support-2026-07-28'),
      ('SLIM — A2A sur binding expérimental','https://slim.agntcy.org/latest/slim/integrations/a2a/'),
      ('NATS — JetStream','https://docs.nats.io/concepts/jetstream'),
      ('NATS — TLS et chiffrement au repos','https://docs.nats.io/learn/security/encryption'),
      ('XMPP — OMEMO','https://xmpp.org/extensions/xep-0384.html'),
      ('RabbitMQ — streams','https://www.rabbitmq.com/docs/streams'),
      ('OASIS — MQTT 5.0','https://docs.oasis-open.org/mqtt/mqtt/v5.0/os/mqtt-v5.0-os.html'),
      ('libp2p — considérations de sécurité','https://docs.libp2p.io/concepts/security/security-considerations/'),
      ('Signal — spécifications cryptographiques','https://signal.org/docs/')]
    def link(n):
        name,url=refs[n];return '<a href="'+url+'">'+name+'</a>'
    sources='<p>Revue de sources primaires au 16 octobre 2026. Les documents latest peuvent évoluer. Aucune installation, aucun benchmark et aucun test réseau n’ont été effectués.</p><ul>'+''.join('<li>'+link(i)+'</li>' for i in range(len(refs)))+'</ul>'
    notice='<div class="notice"><p><strong>Actualisation du 16 octobre 2026 :</strong> Matrix devient le socle recommandé du MVP après ajout des besoins de boîte aux lettres, réception événementielle et éditions Internet/intranet autonome. La cible SLIMRPC/MLS ci-dessous reste une option spécialisée à qualifier ; elle n’est plus le transport unique du produit. Voir l’<a href="../03-recherche/comparatif-socles-messagerie.html">étude des deux meilleures combinaisons</a>.</p></div>'
    recommendations=table(['Rang','Combinaison','Pourquoi / conditions'],[
      ('1 · Recommandée pour le MVP','Matrix + Synapse + PostgreSQL ; client agent avec Matrix Rust SDK ; API et MCP locaux ; adaptateur A2A ; Element facultatif.','Boîte aux lettres, salons et synchronisation déjà définis ; intranet auto-hébergé et Internet avec le même socle. Intégration et performances à qualifier.'),
      ('2 · Alternative à prototyper','XMTP auto-hébergé + SDK XMTP + API/MCP + adaptateur A2A.','Très proche de l’identité cryptographique et du MLS souhaités. Qualification plus incertaine de la version actuelle, du périmètre de réseau et de la maturité opérationnelle ; ne pas supposer une fédération entre backends.')])
    stack=table(['Composant','Choix proposé','Rôle'],[
      ('Protocole et serveur','Matrix / Synapse','Conversations, événements et synchronisation ; serveur sans clés privées de déchiffrement.'),
      ('Base du serveur','PostgreSQL','Persistance selon la configuration Synapse retenue ; contenu E2EE et métadonnées, pas de clés privées des agents.'),
      ('Client de confiance par agent','Daemon Rust avec matrix-sdk','Clés, état cryptographique, synchronisation et boîte locale. Valider la compilation Windows et le stockage protégé sur les systèmes cibles.'),
      ('Intégrations','Adaptateurs API/MCP/A2A ; TypeScript lorsque pertinent','API de lecture/envoi locale authentifiée ; MCP comme outils ; A2A comme opérations agent. Ce sont des composants à développer, pas des compatibilités natives démontrées.'),
      ('Réception','Boucle de synchronisation du daemon + journal local durable','Signal puis récupération du message ; reprise par curseur et déduplication.'),
      ('Interface humaine','Element Web/Desktop facultatif','Inspection par un compte explicitement invité et autorisé. Aucun opérateur n’obtient automatiquement accès aux conversations privées.'),
      ('Déploiement','Édition en ligne et édition intranet autonome','Même protocole et modèle applicatif ; configurations réseau, identité et maintenance propres à chaque édition.')])
    comparison=table(['Piste examinée','Atout','Limite pour Polytalk / conclusion'],[
      ('Matrix / Synapse / SDK','Messagerie, état de salon et synchronisation ; écosystème de clients.','Gestion d’appareils et de clés, métadonnées visibles et exploitation à maîtriser. Premier choix.'),
      ('XMTP','Identités cryptographiques, boîtes et MLS ; SDK agents.','Documentation actuelle en transition vers backend auto-hébergé et SDK en release candidate. Second choix sous conditions.'),
      ('A2A / SLIM / MLS','Intégration RPC entre agents, chiffrement de sessions.','Binding expérimental ; boîte aux lettres et réveil des clients restent à qualifier. Option spécialisée, pas socle unique du MVP.'),
      ('XMPP / OMEMO','Fédération et messagerie ; extension E2EE documentée.','Profil d’extensions et compatibilité des clients à harmoniser ; OMEMO publié comme expérimental. Pas de gain décisif établi face à Matrix.'),
      ('NATS / JetStream','Persistance et reprise orientées événements.','TLS et chiffrement serveur ne constituent pas l’E2EE contre le broker ; identité, contacts et couche E2EE applicative à assembler. Pas de broker supplémentaire au MVP.'),
      ('RabbitMQ / MQTT','Transports événementiels et mécanismes de livraison.','Ne constituent pas à eux seuls le produit de messagerie privée avec identité cryptographique ; couche applicative et clés à construire.'),
      ('libp2p / WebRTC','Connexions directes et canaux sécurisés selon la pile.','Découverte, NAT, relais, persistance et gestion des groupes accroissent le travail produit. Pas de meilleur compromis démontré pour le MVP.'),
      ('Primitives Signal / MLS assemblées sur mesure','Contrôle du protocole et des clés.','Ne fournissent pas à elles seules annuaire, boîte aux lettres et exploitation ; coût de conception et revue supérieur. Pas de cryptographie maison.')])
    write('03-recherche/comparatif-socles-messagerie.html','Polytalk — Étude des socles et deux meilleures combinaisons',[
      ('conclusion','Choix proposé', '<div class="decision"><p><strong>Je recommande Matrix avec Synapse et un connecteur local de confiance par agent.</strong> Element peut servir d’interface humaine facultative ; il n’est pas le moteur de communication des agents. XMTP constitue la seconde combinaison à prototyper si MLS et les identités cryptographiques priment sur la maturité et la fédération.</p></div>'+recommendations+'<p>Classement qualitatif propre au projet, sans benchmark : priorité à la confidentialité, à la boîte aux lettres durable, aux notifications, à l’intranet autonome puis à l’interopérabilité. L’équipe, les volumes et le budget ne sont pas connus. Aucune exploration ne peut garantir avoir couvert toutes les technologies existantes ; les principales familles pertinentes sont comparées ici.</p>'),
      ('element','Element est-il le meilleur choix ?','<p>Matrix est le protocole ; Synapse est un serveur ; Element est une famille de clients et de distributions. Element X s’appuie sur le Matrix Rust SDK. Pour des agents, utiliser le SDK et les API plutôt qu’automatiser l’interface Element. '+link(4)+' ; '+link(2)+'.</p><p>Le SDK fournit notamment des fonctions de chiffrement et de synchronisation et vise aussi les bots. Le daemon local Polytalk restera nécessaire pour traduire les messages en événements adaptés à chaque agent. '+link(2)+'.</p><p>Choix proposé : Synapse auto-hébergé avec PostgreSQL pour l’évaluation. Examiner licences des composants et support avant le déploiement commercial ; la documentation d’Element présente ESS Community pour l’évaluation et les usages non professionnels. Ne pas confondre ce positionnement avec une conclusion juridique sur l’ensemble de Matrix. ESS Pro est une option de support à chiffrer, pas un achat décidé. '+link(5)+' ; '+link(3)+'.</p>'),
      ('stack','Combinaison technique recommandée',stack+'<p>Matrix fournit un socle de messagerie, pas une conformité A2A automatique. Le mapping A2A ↔ événements Matrix devra être versionné, préserver corrélation, erreurs et flux, et être testé. Il ne doit pas être annoncé comme un binding A2A standard sans spécification et vérification.</p>'),
      ('crypto','Chiffrement et identité','<p>Le chiffrement Matrix standard repose sur Olm/Megolm ; il ne faut pas le présenter comme MLS. '+link(1)+'. Le contenu est déchiffré dans le daemon autorisé. Les identifiants, membres, informations d’état et flux réseau ne deviennent pas tous secrets. Les politiques de vérification des appareils et de rotation sont obligatoires pour le mode privé.</p><p>L’identifiant stable Polytalk doit être relié de manière vérifiable à l’utilisateur Matrix et aux appareils autorisés. Un identifiant Matrix seul n’est pas une preuve cryptographique de type wallet. Ne pas ajouter de blockchain sans besoin démontré. Les sauvegardes de clés, récupération et arrivée d’un appareil demandent une politique explicite.</p><p>Une passerelle centrale qui lit puis rechiffre devient une extrémité de confiance. Ne pas la présenter comme un simple relais E2EE. Éviter une pile Matrix + SLIM + deux mécanismes de groupe sur chaque message : choisir un chemin de livraison par conversation.</p>'),
      ('alternative','Seconde combinaison : XMTP','<p>XMTP décrit une destination stable de type inbox, des identités et des installations avec leurs propres clés. Cela correspond bien à l’intention initiale du projet. '+link(7)+'. Son socle utilise MLS pour les conversations, mais conserve des métadonnées observables. '+link(6)+'.</p><p>Point bloquant découvert : le quickstart actuel propose un SDK 8.0.0-rc2 ; il ne faut pas le traiter comme une version stable validée pour Polytalk. '+link(9)+'. La documentation de migration indique que les contacts doivent rejoindre le même réseau auto-hébergé pour recréer des conversations actives ; importer l’historique ne suffit pas. '+link(8)+'.</p><p>Prototyper seulement sur un couple backend/SDK épinglé. Vérifier identité non financière, dépendances de démarrage, fonctionnement sans Internet, stockage, licences et limites. L’existence d’un guide auto-hébergé ne démontre pas une fédération universelle entre réseaux isolés.</p>'),
      ('alternatives','Autres pistes examinées',comparison+'<p>Références spécifiques : '+link(16)+' ; '+link(19)+' ; '+link(17)+' ; '+link(18)+' ; '+link(20)+' ; '+link(21)+' ; '+link(22)+' ; '+link(23)+'. Les conclusions de priorité et de coût d’assemblage sont des appréciations de conception, pas des résultats de performance mesurés.</p>'),
      ('editions','Éditions Internet et intranet autonome','<p><strong>En ligne :</strong> service accessible sur Internet avec TLS, gestion des comptes et fédération contrôlée si retenue. Aucun contenu privé dans les services push ou journaux.</p><p><strong>Intranet hors Internet :</strong> serveur, base, annuaire, authentification, certificats et maintenance disponibles localement. Déployer un paquet versionné avec dépendances et images préparées ; aucun téléchargement de CDN ni service cloud obligatoire à l’exécution. La fédération extérieure est désactivée ; une fédération interne peut être qualifiée séparément.</p><p>Les postes restent connectés au réseau local. Si tous les réseaux sont absents, seule une file locale est possible et l’échange attend une reconnexion. Un intranet isolé ne permet pas d’appeler les modèles cloud : prévoir agents locaux ou fournisseurs internes. Aucun tunnel sortant automatique.</p>'),
      ('decision','Décision et conditions de révision','<p>Retenir Matrix comme socle de référence du MVP, garder XMTP comme alternative et réserver SLIM/MLS à une extension spécialisée. L’ADR-004 antérieure devient une piste conditionnelle et non une obligation de transport général. La progression API/MCP → A2A → validation SLIM/MLS est conservée, avec Matrix préparé au socle et sa réception événementielle dès la première étape.</p><p>Revoir ce choix si l’exigence devient « MLS obligatoire sur chaque conversation », si les volumes mesurés le justifient ou si le PoC Matrix échoue à l’intranet autonome, aux notifications ou à la récupération des clés. Aucun coût ou SLA n’est inventé.</p>'),
      ('glossaire','Glossaire',glossary),('sources','Sources et limites',sources)])
    notification_table=table(['Mécanisme','Usage proposé','Limite'],[
      ('Synchronisation Matrix persistante','Canal principal du daemon ; reprise par curseur, pagination des trous d’historique et déduplication.','Recevoir un événement ne prouve ni déchiffrement ni remise au modèle.'),
      ('SSE sur API locale authentifiée','Signal unidirectionnel vers les intégrations compatibles ; reprise par identifiant lorsque prévue.','Ce flux Polytalk est à concevoir ; ce n’est pas le transport standard de Matrix.'),
      ('WebSocket','Option si échange bidirectionnel continu nécessaire.','Plus de gestion des connexions ; ne pas doubler le canal par défaut sans besoin.'),
      ('Webhook HTTPS signé','Alerte vers un orchestrateur préenregistré et autorisé.','Signal minimal sans contenu ; rejeu, répétition, indisponibilité et destinations SSRF à contrôler.'),
      ('Polling avec curseur','Solution de repli pour un client sans réception poussée.','Latence et coût réseau ; ce n’est pas du temps réel garanti.'),
      ('Push système mobile','Signal secondaire facultatif pour interface humaine.','APNs/FCM dépendraient d’Internet ; ne pas en faire une dépendance de l’intranet.'),
      ('MCP seul','Outils de consultation, lecture et accusé de traitement ; abonnements selon client.','Une notification MCP ne garantit pas le déclenchement du modèle. Pas de réveil universel.')])
    client_table=table(['Client','Piste officielle établie','Choix Polytalk / réserve'],[
      ('Claude Code','Channels : serveur MCP local pouvant pousser des événements dans une session ouverte ; research preview.','Connecteur channel Polytalk à développer et à autoriser. La disponibilité dépend de l’authentification, de l’organisation et des versions. Aucun réveil d’un processus fermé.'),
      ('Codex','App Server : démarrage/reprise de conversation et lancement de tour via protocole documenté.','Adaptateur vers une instance gérée et autorisée par le propriétaire. Ne pas supposer un accès arbitraire aux chats du bureau Codex ; préserver les approbations et le sandbox.'),
      ('Gemini CLI','Mode headless pour un travail programmatique ; hooks liés au cycle de vie existant.','Worker local préautorisé pouvant lancer un traitement isolé ; un hook Notification sortant n’est pas un récepteur universel de messagerie.'),
      ('Autres agents / SDK','Contrat à fournir : écouter, lire, confirmer et éventuellement démarrer un travail.','API et polling restent le profil minimum ; validation spécifique par version. « Muse de Meta » reste à identifier.')])
    write('02-architecture/reception-notifications-deploiement.html','Polytalk — Réception, notifications et éditions en ligne/intranet',[
      ('besoin','Exigences confirmées','<p>Chaque agent doit pouvoir savoir qu’il a reçu un message. Un agent actif reçoit un événement ; un agent déconnecté retrouve les messages conservés à son retour. Le produit doit disposer d’une édition en ligne et d’une édition intranet utilisable sans Internet.</p><p>Le réveil automatique est optionnel, limité à un runtime autorisé par le propriétaire. Aucun simple message ne donne le droit de lancer une commande ou de modifier un projet. Le choix du socle recommandé est détaillé dans l’<a href="../03-recherche/comparatif-socles-messagerie.html">étude comparative</a>.</p>'),
      ('architecture','Architecture recommandée','<div class="flow" role="img" aria-label="Serveur Matrix, daemon local de réception, puis adaptateur vers agent autorisé"><div><b>Serveur Matrix</b>Événements conservés<br>Contenu chiffré</div><span aria-hidden="true">→</span><div><b>Daemon local</b>Synchronise et vérifie<br>Journalise la remise</div><span aria-hidden="true">→</span><div><b>Adaptateur agent</b>Signale le message<br>Déclenchement autorisé</div></div><p>Le daemon maintient une synchronisation Matrix avec état persistant. Le SDK fournit les fonctions de clients ; il ne remplace pas notre journal de traitement. '+link(0)+' ; '+link(2)+'.</p><p>Préférer une connexion sortante du poste vers le serveur : aucun port public à ouvrir sur chaque poste. Les échanges entre daemon et adaptateurs utilisent IPC ou interface locale authentifiée, sans exposition générale du contenu en clair.</p>'),
      ('etats','États observables et signification','<ol><li><strong>Déposé :</strong> le serveur a accepté l’événement.</li><li><strong>Synchronisé :</strong> le daemon l’a enregistré localement de manière durable.</li><li><strong>Déchiffré et vérifié :</strong> clés, identité et schéma ont passé les contrôles.</li><li><strong>Signalé :</strong> l’adaptateur a accepté l’avis de disponibilité.</li><li><strong>Remis au runtime :</strong> le client a confirmé son admission ; ce n’est pas une preuve de compréhension du modèle.</li><li><strong>Traitement terminé :</strong> résultat applicatif explicite, si un traitement a été autorisé.</li></ol><p>États d’exception : clés manquantes, destinataire non autorisé, agent indisponible, traitement refusé ou expiré. Une alerte perdue ne supprime jamais le message durable. Un accusé Matrix de lecture ne remplace pas un accusé de traitement Polytalk.</p>'),
      ('mecanismes','Meilleures pistes de notification',notification_table),
      ('clients','Intégration effective aux agents',client_table+'<p>Sources : '+link(10)+' ; '+link(11)+' ; '+link(12)+' ; '+link(13)+' ; '+link(14)+'. Vérification documentaire uniquement ; aucune compatibilité installée n’est prouvée.</p><p>Point de version important : le MCP récent utilise des abonnements explicites pour les notifications de changement. '+link(15)+'. Les channels Claude ne sont pas un mécanisme MCP portable : la documentation signale des restrictions sur la révision 2026-07-28. Figer la combinaison client/protocole avant implémentation et conserver le polling de repli.</p>'),
      ('durabilite','Reprise, rediffusion et contrôle des doublons','<p>Conception Polytalk : transaction locale enregistrant l’événement, son identifiant et le travail de notification avant d’avancer le curseur durable. Le daemon accuse réception du signal séparément de son traitement. En cas de crash, reprendre les travaux non terminés ; dédupliquer par identité de destinataire et identifiant de message.</p><p>Un historique de synchronisation limité exige de combler les trous selon l’API et la rétention disponible. La présence du message sur le serveur ne garantit pas que le client dispose encore des clés : restaurer l’état cryptographique ou signaler le problème. Ne pas réinitialiser une identité à chaque redémarrage.</p><p>Prévoir retries bornés, temporisation progressive, file d’échecs et relecture contrôlée. Pour des actions externes, propager une clé d’idempotence lorsque le service le permet. Sinon, signaler une exécution ambiguë après crash au lieu de promettre « exactement une fois ».</p>'),
      ('reveil','Réveil autorisé et agent occupé','<p>Trois modes : notification seule ; traitement automatique de contacts et tâches autorisés ; validation humaine avant traitement. Le défaut proposé est la notification seule. Un lanceur local configuré peut démarrer un worker ou une session gérée avec identité, budget, durée et outils limités.</p><p>Si l’agent est occupé, mettre les messages en file ; ne pas interrompre son tour par défaut. L’injection dans un tour actif n’est permise que si l’intégration et la politique le prévoient. Empêcher les boucles entre agents : ne pas répondre aux accusés, conserver corrélation et causalité, limiter échanges et coûts.</p><p>Une machine éteinte ne reçoit aucun événement local. Le serveur conserve les messages suivant sa rétention ; la reprise attend le redémarrage. Le wake-on-LAN ou le pilotage de postes est hors MVP et demanderait une autorisation et une étude séparées.</p>'),
      ('editions','Deux éditions du même produit',table(['Édition','Architecture proposée','Dépendances'],[
        ('En ligne / Internet','Synapse et base sur infrastructure accessible ; daemon par agent ; TLS et identité configurés. Fédération sur politique explicite.','Hébergement et maintenance ; modèles cloud uniquement selon autorisation et connectivité.'),
        ('Hors ligne / intranet','Synapse, base, comptes, DNS et certificats internes ; clients et daemons sur LAN. Aucun accès Internet requis pour la messagerie.','Paquet d’installation complet, autorité de confiance interne, mises à jour signées importables et sauvegardes locales. Modèles locaux ou internes pour l’IA.'),
        ('Poste momentanément hors réseau','File locale, état de clés et curseurs préservés ; reprise au retour sur son serveur.','Aucune communication entre machines sans réseau ; pas de promesse de livraison immédiate.')])+ '<p>Les éditions partagent le protocole et les fonctionnalités de base ; elles ne synchronisent pas automatiquement entre elles à travers une isolation réseau. Tout transfert entre domaines doit faire l’objet d’un besoin explicite et d’une conception dédiée.</p>'),
      ('validation','Plan de validation indispensable','<ul><li>Message en ligne : mesurer séparément dépôt, synchronisation et remise au runtime ; définir un objectif de latence après mesure.</li><li>Agent arrêté, puis lancé ; daemon arrêté ; serveur redémarré ; poste éteint : vérifier la reprise, sans perte silencieuse ni action doublée.</li><li>Rupture réseau et historique tronqué : pagination et rattrapage corrects.</li><li>Clé manquante ou appareil non vérifié : état d’erreur explicite et aucune remise en clair à un relais.</li><li>Agent occupé : file respectée ; aucun mélange de conversations.</li><li>Webhook rejoué, identité révoquée, message hostile et boucle de réponses : refus ou limites vérifiables.</li><li>Intranet isolé : couper DNS Internet et egress ; vérifier installation depuis paquet local, authentification, échange et notification sans APNs/FCM/CDN ni modèle cloud.</li><li>Tester séparément Claude Code, Codex et Gemini CLI sur les versions et droits annoncés.</li></ul><p>Tous ces tests restent à exécuter. Le système n’a pas encore été implémenté.</p>'),
      ('glossaire','Glossaire',glossary),('sources','Sources',sources)])

    changes=[
      ('01-cadrage/vision.html','Polytalk — Vision et besoins initiaux'),
      ('02-architecture/decisions.html','Polytalk — Orientations d’architecture et sécurité'),
      ('03-recherche/protocoles-connecteurs.html','Polytalk — Veille sur les protocoles et connecteurs'),
      ('04-livrables/feuille-de-route-integration.html','Polytalk — Feuille de route d’intégration'),
      ('00-pilotage/index.html','Polytalk — Registre documentaire'),
      ('00-pilotage/verification-documentaire.html','Polytalk — Compte rendu de vérification documentaire')]
    for rel,title in changes:
        items=load(rel)
        prefix='../' if not rel.startswith('02-architecture/') else '../'
        summary='<div class="decision"><p><strong>Orientation actuelle : Matrix/Synapse comme socle du MVP, XMTP comme alternative à qualifier.</strong> Element est une interface humaine facultative. La cible SLIMRPC/MLS antérieure reste une option spécialisée, non le transport unique. Conserver API/MCP → A2A → validation SLIM/MLS, avec le socle Matrix et la réception événementielle préparés dès la première étape.</p></div><p>Exigences confirmées : notifications aux agents actifs, rattrapage après déconnexion, et deux éditions — en ligne sur Internet et hors Internet sur intranet. Le réveil d’un agent est assuré seulement par un runtime préautorisé.</p><p><a href="'+prefix+'03-recherche/comparatif-socles-messagerie.html">Comparatif et choix des deux combinaisons</a> · <a href="'+prefix+'02-architecture/reception-notifications-deploiement.html">Réception, notifications et déploiement</a>.</p>'
        if rel.startswith('02-architecture/'):
            summary='<p>ADR-005 · 16 octobre 2026 · Socle de référence recommandé pour le MVP ; validation technique à exécuter.</p>'+summary
            heading='ADR-005 · Socle Matrix, réception et éditions Internet/intranet'
        else:heading='Orientation actualisée · Matrix, réception et deux éditions'
        items=[x for x in items if x[0]!='actualisation-socle']
        items.insert(0,('actualisation-socle',heading,summary))
        items=[(i, h+' · Option spécialisée, révisée par ADR-005' if i=='adr-004' else h,b) for i,h,b in items]
        if rel=='04-livrables/feuille-de-route-integration.html':
            items=put(items,('qualification-editions','Qualification Matrix et éditions avant livraison','<p>Le socle Matrix et la réception durable sont préparés avec API/MCP. Qualifier installation locale, identité, clés, synchronisation, rattrapage et remise aux runtimes. L’adaptateur A2A vient ensuite. La validation SLIM/MLS reste une branche spécialisée et ne bloque pas le MVP Matrix si cette branche est désactivée. Le mode Matrix privé doit néanmoins passer ses propres tests E2EE.</p><p>Livrables supplémentaires : paquet intranet complet et versionné, profil Internet, matrice de compatibilité des agents, rapport de coupure Internet et procédure de mise à jour hors ligne. Aucun lancement d’agent, tunnel ni abonnement ne sera activé par défaut.</p>'))
        if rel=='00-pilotage/verification-documentaire.html':
            items=put(items,('verification-matrix','Vérification de la présente extension','<p>Sources officielles Matrix, Element, XMTP et interfaces des clients agents consultées. La vérification Codex s’appuie sur le guide OpenAI Docs et la documentation officielle App Server. Comparaison qualitative, sans benchmark ni installation. Contrôles HTML et liens internes relancés. Le contrôle visuel navigateur reste non réalisé.</p>'))
        items=put(items,('glossaire','Glossaire',glossary))
        write(rel,title,items,'0.4')
    p='02-architecture/transport-a2a-slim-mls.html'
    items=load(p);items.insert(0,('statut-actuel','Statut actuel de cette architecture',notice))
    write(p,'Polytalk — Option spécialisée A2A sur SLIM et MLS',items,'1.1')
    write('05-archives/2026-10-16-matrix-notifications-editions.html','Polytalk — Archive Matrix, notifications et éditions',[
      ('besoins','Besoins recueillis','<p>Le porteur ajoute Matrix, demande d’étudier Element et les autres pistes pour proposer les deux meilleures combinaisons, puis confirme la notification des messages aux agents et la disponibilité d’une édition Internet et d’une édition intranet hors Internet.</p>'),
      ('resultat','Résultat et statut','<p>Recommandation de conception : Matrix/Synapse, client local avec Matrix Rust SDK, API/MCP, adaptateur A2A, notifications durables et Element facultatif. XMTP est la seconde option à qualifier. SLIM/MLS reste une extension spécialisée. Aucun nouveau logiciel installé, aucune intégration testée. Le contenu et les clés restent dans les composants de confiance des agents.</p>'),
      ('glossaire','Glossaire',glossary)])
